    if(tcaIdx !== -1) clean = clean.substring(0, tcaIdx);
    var plIdx = clean.indexOf('<plan>');
    if(plIdx !== -1) clean = clean.substring(0, plIdx);
    var thIdx = clean.indexOf('<think>');
    if(thIdx !== -1) clean = clean.substring(0, thIdx);

